import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring, Easing } from '../remotionShim';
// Schema definition


export type CalendarStackProps = Record<string, any>;

// Font Loader (Standard Pattern - even if minimal text, good for stability)
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};

// SVG Icon Component
const CalendarIcon: React.FC<{
  size: number;
  color: string;
  highlightColor: string;
  fillColor: string;
  strokeWidth: number;
  highlightOpacity: number;
}> = ({ size, color, highlightColor, fillColor, strokeWidth, highlightOpacity }) => {
  
  // Grid generation
  const rows = 4;
  const cols = 5; // simplified grid
  const cellW = 80 / cols;
  const cellH = 60 / rows;
  const startY = 30; // Header takes top 30%
  const startX = 10;

  // The 7th cell (index 6) will be highlighted (Row 1, Col 1 if 0-indexed)
  // Let's pick a nice center-ish cell, e.g., Row 1, Col 2
  const highlightRow = 1;
  const highlightCol = 2;
  const highlightX = startX + highlightCol * cellW;
  const highlightY = startY + highlightRow * cellH;

  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 100 100"
      style={{ overflow: "visible" }}
    >
      {/* Card Background */}
      <rect
        x="0"
        y="0"
        width="100"
        height="100"
        rx="8"
        fill={fillColor}
        stroke={color}
        strokeWidth={strokeWidth}
      />
      
      {/* Header Line */}
      <line
        x1="0"
        y1={startY}
        x2="100"
        y2={startY}
        stroke={color}
        strokeWidth={strokeWidth}
      />

      {/* Grid Lines - Vertical */}
      {Array.from({ length: cols - 1 }).map((_, i) => (
        <line
          key={`v-${i}`}
          x1={startX + (i + 1) * cellW}
          y1={startY}
          x2={startX + (i + 1) * cellW}
          y2={90}
          stroke={color}
          strokeWidth={strokeWidth * 0.5}
          strokeLinecap="round"
          opacity={0.5}
        />
      ))}

      {/* Grid Lines - Horizontal */}
      {Array.from({ length: rows - 1 }).map((_, i) => (
        <line
          key={`h-${i}`}
          x1={startX}
          y1={startY + (i + 1) * cellH}
          x2={90}
          y2={startY + (i + 1) * cellH}
          stroke={color}
          strokeWidth={strokeWidth * 0.5}
          strokeLinecap="round"
          opacity={0.5}
        />
      ))}

      {/* Highlight Cell */}
      <rect
        x={highlightX + strokeWidth}
        y={highlightY + strokeWidth}
        width={cellW - strokeWidth * 2}
        height={cellH - strokeWidth * 2}
        fill={highlightColor}
        opacity={highlightOpacity}
        rx="2"
      />
    </svg>
  );
};

const CalendarStack: React.FC<CalendarStackProps> = ({
  backgroundColor = "#f0f2f5",
  transparentBackground = false,
  durationInSeconds = 6,
  calendarColor = "#2d3436",
  highlightColor = "#e17055",
  cardBackgroundColor = "#ffffff",
  stackCount = 5,
  iconSize = 250,
  strokeWidth = 4,
}) => {
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Background handling
  const finalBgColor = transparentBackground ? "transparent" : backgroundColor;

  // Animation Parameters
  const introDuration = 30; // Frames for first appearance
  const cycleDuration = 35; // Frames per new calendar
  const highlightDuration = 15; // Highlight flash duration
  const stackOverlap = iconSize * 0.25; // How much they overlap vertically

  // Calculate current "step" of the animation
  // Step 0: Intro
  // Step 1..N: Stacking
  
  // Total logic:
  // We want to control the "camera" or global Y offset based on how many items have appeared.
  // As a new item appears at the bottom, the whole group moves up.
  
  // Clamped frame for the main sequence to ensure it stops statically at the end
  const sequenceStartFrame = introDuration;
  
  // Calculate how many items *should* be visible
  // We use a float value to drive the spring for smooth transitions
  const progressRaw = Math.max(0, (frame - sequenceStartFrame) / cycleDuration);
  const activeIndex = Math.min(stackCount - 1, Math.floor(progressRaw));
  
  // "Camera" moves up as index increases
  // If activeIndex is 0, offset is 0.
  // If activeIndex is 1, offset is 1 unit of height (stackOverlap).
  const springConfig = { damping: 14, stiffness: 80, mass: 1 };
  
  // We drive the global lift with a spring based on the floored progress (steps)
  const liftTrigger = interpolate(
    frame,
    [sequenceStartFrame, sequenceStartFrame + (stackCount - 1) * cycleDuration],
    [0, stackCount - 1],
    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );

  // But we want it to 'step' then 'spring'.
  // Create a stepped driver
  const steppedDriver = Math.floor(liftTrigger); 
  // To make it smooth, we spring the stepped value, but we need to delay the spring until the cycle starts
  // Actually, simplest is to spring the raw progress but clamp it to integers? No.
  // Let's spring the integer 'activeIndex'.
  
  const liftSpring = spring({
    frame: frame - sequenceStartFrame,
    fps,
    config: springConfig,
    from: 0,
    to: activeIndex, 
  });
  
  // If frame < sequenceStartFrame, liftSpring might behave oddly if we don't clamp.
  // Safe lift value:
  const globalLift = frame < sequenceStartFrame ? 0 : liftSpring;
  
  return (
    <AbsoluteFill style={{ backgroundColor: finalBgColor }}>
      <AbsoluteFill
        style={{
          justifyContent: "center",
          alignItems: "center",
        }}
      >
        <div
          style={{
            position: "relative",
            width: width,
            height: height,
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
          }}
        >
            {/* 
                Render Loop 
                We render ALL items, but control their visibility/position.
                Item 0 is the "First" (Oldest). 
                Item N is the "Newest".
                
                Arrangement:
                Item 0 is at Top.
                Item N is at Bottom.
                
                Motion:
                When Item N appears, it starts at Scale 0/Opacity 0 at the "spawn point".
                The "spawn point" is effectively the center of the screen, adjusted by the global lift.
            */}
            {Array.from({ length: stackCount }).map((_, index) => {
                // Timing for this specific item
                // Item 0 appears at frame 0 (Intro).
                // Item 1 appears at sequenceStart + 0.
                // Item 2 appears at sequenceStart + cycleDuration.
                
                let itemStartFrame = 0;
                if (index > 0) {
                    itemStartFrame = sequenceStartFrame + (index - 1) * cycleDuration;
                }

                // Entrance Animation
                // Item 0: Simple Fade/Scale
                // Item > 0: Slide/Fade in?
                const entranceDelay = index === 0 ? 0 : itemStartFrame;
                const activeFrame = frame - entranceDelay;
                
                const entranceSpring = spring({
                    frame: activeFrame,
                    fps,
                    config: { damping: 15, stiffness: 120 },
                });

                // Highlight Animation
                // Occurs shortly after entrance
                // For Item 0: Happens at frame 15-30
                // For Item > 0: Happens at itemStartFrame + 15
                const highlightStart = entranceDelay + 10;
                const highlightVal = interpolate(
                    frame,
                    [highlightStart, highlightStart + highlightDuration, highlightStart + highlightDuration + 15],
                    [0, 1, 0], // Flash on then off
                    { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.ease) }
                );

                // Position Calculation
                // Base Position: Center of screen.
                // Stack Offset: Each item is `stackOverlap` pixels below the previous.
                // Local Y = index * stackOverlap.
                // Global Y correction = -globalLift * stackOverlap.
                // This keeps the "Current" item roughly centered.
                
                const localY = index * stackOverlap;
                const globalYCorrection = -(globalLift * stackOverlap);
                const finalY = localY + globalYCorrection;

                // Scale/Opacity for entrance
                const scale = interpolate(entranceSpring, [0, 1], [0.8, 1]);
                const opacity = interpolate(activeFrame, [0, 10], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

                // Z-Index: Newest on Top?
                // If Item 1 is below Item 0 physically (higher Y), it should probably be 'under' Item 0 to look like a stack growing down?
                // Request: "Slides upward, stacking vertically".
                // Let's try zIndex = stackCount - index (Oldest on top).
                const zIndex = stackCount - index;

                return (
                    <div
                        key={index}
                        style={{
                            position: "absolute",
                            transform: `translateY(${finalY}px) scale(${scale})`,
                            opacity,
                            zIndex,
                            transformOrigin: "center center",
                            // Shadow for depth
                            filter: `drop-shadow(0px 10px 20px rgba(0,0,0,0.15))`,
                        }}
                    >
                        <CalendarIcon
                            size={iconSize}
                            color={calendarColor}
                            highlightColor={highlightColor}
                            fillColor={cardBackgroundColor}
                            strokeWidth={strokeWidth}
                            highlightOpacity={highlightVal}
                        />
                    </div>
                );
            })}
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default CalendarStack;